/// <summary>
/// Changes text color of SalesQuotaitonLines based on KCS_NotCalculated
/// </summary>
/// <param name="_sender">FormDataSource</param>
/// <param name="_e">FormDataSourceEventArgs</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter _sender required in signature'),
 FormDataSourceEventHandler(formDataSourceStr(SalesQuotationTable, SalesQuotationLine), FormDataSourceEventType::DisplayOptionInitialize)]
public static void SalesQuotationLine_OnDisplayOptionInitialize(FormDataSource _sender, FormDataSourceEventArgs _e)
{
    FormDataSourceDisplayOptionInitializeEventArgs  event = _e as FormDataSourceDisplayOptionInitializeEventArgs;
    SalesQuotationLine              salesQuotationLine = event.record();
    int                             textColor;

    switch(salesQuotationLine.KCS_NotCalculated)
    {
        case NoYes::Yes:
            textColor = WinAPI::RGB2int( 0,0,255 );
            break;
        default:
            textColor = WinAPI::RGB2int( 0,0,0 );
            break;
    }

    event.displayOption().textColor(textColor);
}

