public static void AVABuildingProject_KCS_KBVRequestId_OnLookup(FormControl sender, FormControlEventArgs e)
{
    SysTableLookup          sysTableLookup = SysTableLookup::newParameters(tableNum(KCS_KBVRequestTable),sender);
