/// <summary>
/// designed from AVA
/// </summary>
/// <param name="sender">sebder</param>
/// <param name="e">e</param>
[SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    FormControlEventHandler(formControlStr(SalesQuotationTable, SalesQuotationTable_KCS_RefQuotationId1), FormControlEventType::Lookup)]
public static void SalesQuotationTable_KCS_RefQuotationId1_OnLookup(FormControl sender, FormControlEventArgs e)
{
    FormRun             formRun = sender.formRun();
    FormDataSource      callerDS = formRun.dataSource(tableStr(SalesQuotationTable));
    SalesQuotationTable salesQuotationTable = callerDS.cursor();
    SysTableLookup      sysTableLookup = SysTableLookup::newParameters(tableNum(SalesQuotationTable),sender);

    sysTableLookup.addLookupfield(fieldNum(SalesQuotationTable,QuotationId),true);
    sysTableLookup.addLookupfield(fieldNum(SalesQuotationTable,CustAccount));
    sysTableLookup.addLookupfield(fieldNum(SalesQuotationTable,BusRelAccount));
    sysTableLookup.addLookupfield(fieldNum(SalesQuotationTable,KCS_KBVBuildingProjectID));
    sysTableLookup.addLookupfield(fieldNum(SalesQuotationTable,KCS_KBVRequestId));

    Query                       query = new Query();
    QueryBuildDataSource        salesQuotationTableDS = query.addDataSource(tableNum(SalesQuotationTable));
    //salesQuotationTableDS.addRange(fieldNum(SalesQuotationTable,KCS_KBVBuildingProjectID)).value(salesQuotationTable.KCS_KBVBuildingProjectID);
    salesQuotationTableDS.addRange(fieldNum(SalesQuotationTable,QuotationId)).value(strfmt('!%1',salesQuotationTable.QuotationId)); 

    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}

